{
  "staging.stg_jira__user": {
    "items": [
      {
        "problem": "Duplicate user IDs are not removed or otherwise reconciled despite the required uniqueness constraint.",
        "about": "requirement",
        "evidence_in_work": "from raw.user where id is not null",
        "source": "user_id ... constraints: [not_null, unique]",
        "importance": 3,
        "reason": "Duplicates would multiply comments, issues, and downstream user metrics, although the sampled output had unique IDs."
      },
      {
        "problem": "Missing or blank display names are replaced with IDs and existing names are trimmed rather than simply validating the required display name.",
        "about": "requirement",
        "evidence_in_work": "coalesce(nullif(trim(name), ''), cast(id as varchar)) user_display_name",
        "source": "user_display_name ... constraints: [not_null]",
        "importance": 2,
        "reason": "This invents display names and changes text used in profiles and conversations without an explicit correction rule."
      }
    ],
    "fewer_reason": "Only two concrete concerns are supported by the visible user transformation and contract."
  },
  "staging.stg_jira__project": {
    "items": [
      {
        "problem": "Duplicate project IDs are resolved by an arbitrary tied ordering that may retain an incorrect project record.",
        "about": "data",
        "evidence_in_work": "row_number() over(partition by id order by id)=1",
        "source": "project_id ... constraints: [not_null, unique]",
        "importance": 2,
        "reason": "Conflicting duplicate attributes could change project names and lead assignments, but duplicates were not demonstrated."
      }
    ],
    "fewer_reason": "The explicit key and name validation rules otherwise appear implemented."
  },
  "staging.stg_jira__issue": {
    "items": [
      {
        "problem": "Estimate and time-spent fields prefer underscore-prefixed columns without establishing whether those columns are the intended seconds measures.",
        "about": "data",
        "evidence_in_work": "coalesce(_original_estimate,original_estimate)",
        "source": "raw.issue columns include _original_estimate, original_estimate, _remaining_estimate, remaining_estimate, _time_spent, time_spent",
        "importance": 4,
        "reason": "Choosing the wrong parallel measure would affect estimates, hours, and financial metrics throughout the pipeline."
      },
      {
        "problem": "Timezone suffixes are stripped rather than interpreted when converting issue timestamps.",
        "about": "data",
        "evidence_in_work": "regexp_replace(created, ' [+-][0-9]{4}$', '')",
        "source": "standardized timestamps",
        "importance": 4,
        "reason": "The observed +0800 values become naive local times, potentially shifting runtime ages and comparisons across offsets."
      },
      {
        "problem": "Required issue keys and successfully parsed required timestamps are not validated.",
        "about": "requirement",
        "evidence_in_work": "where id is not null and created is not null and updated is not null and project is not null",
        "source": "issue_key, created_at, updated_at ... constraints: [not_null]",
        "importance": 3,
        "reason": "A non-null malformed timestamp can become NULL through try_cast, while a NULL key passes the filter."
      },
      {
        "problem": "Negative estimates, time spent, and work ratios are carried into downstream models whose contracts require non-negative values.",
        "about": "requirement",
        "evidence_in_work": "cast(work_ratio as double) work_ratio",
        "source": "original_estimate_seconds IS NULL OR original_estimate_seconds >= 0; work_ratio IS NULL OR work_ratio >= 0",
        "importance": 3,
        "reason": "Invalid measures would violate analytical model tests and distort duration and investment summaries."
      },
      {
        "problem": "Duplicate issues are selected using lexicographic raw timestamp ordering rather than parsed chronological ordering.",
        "about": "data",
        "evidence_in_work": "partition by id order by updated desc nulls last",
        "source": "raw.issue.updated ... VARCHAR",
        "importance": 2,
        "reason": "Mixed timestamp formats or offsets could select an older duplicate, although sampled issue IDs were unique."
      }
    ],
    "fewer_reason": "Five distinct supported concerns were found; additional source-mapping errors cannot be established from the supplied material."
  },
  "staging.stg_jira__sprint": {
    "items": [
      {
        "problem": "Sprint timestamps lose their timezone offsets during parsing.",
