        "evidence_in_work": "regexp_replace(start_date, ' [+-][0-9]{4}$', '')",
        "source": "Cleaned sprint data with validated date ranges and consistent naming",
        "importance": 3,
        "reason": "Sprint boundaries and runtime active flags can be shifted when offsets are meaningful."
      },
      {
        "problem": "Sprint ID uniqueness is not enforced.",
        "about": "requirement",
        "evidence_in_work": "from raw.sprint where id is not null and trim(id)<>''",
        "source": "sprint_id ... constraints: [not_null, unique]",
        "importance": 3,
        "reason": "Duplicate sprints would change synthetic assignments and could duplicate sprint-level outputs."
      },
      {
        "problem": "Reversed sprint date ranges are not checked before downstream non-negative duration calculations.",
        "about": "requirement",
        "evidence_in_work": "try_cast(... end_date ... as timestamp) ended_at",
        "source": "planned_duration_days IS NULL OR planned_duration_days >= 0",
        "importance": 2,
        "reason": "Invalid ranges could produce negative planned durations and incorrect snapshot selection."
      }
    ],
    "fewer_reason": "Three supported concerns were found."
  },
